actions.body:
{
  "channel": "{{_flow.SLACK_CHANNEL}}",
  "text": "Approval requested for {{issue.key}}: {{issue.fields.summary}}",
  "blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Approval requested*\n<{{baseUrl}}/browse/{{issue.key}}|{{issue.key}}> {{issue.fields.summary}}"
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Type*\n{{issue.fields.issuetype.name}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Priority*\n{{#if issue.fields.priority.name}}{{issue.fields.priority.name}}{{else}}None{{/if}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Reporter*\n{{#if issue.fields.reporter.displayName}}{{issue.fields.reporter.displayName}}{{else}}Unknown{{/if}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Project*\n{{issue.fields.project.name}}"
        }
      ]
    },
    {
      "type": "actions",
      "block_id": "jira_approval",
      "elements": [
        {
          "type": "button",
          "action_id": "jira_approve",
          "style": "primary",
          "text": {
            "type": "plain_text",
            "text": "Approve"
          },
          "value": "{{issue.key}}",
          "confirm": {
            "title": {
              "type": "plain_text",
              "text": "Approve {{issue.key}}?"
            },
            "text": {
              "type": "mrkdwn",
              "text": "This transitions the Jira work item and cannot be undone from Slack."
            },
            "confirm": {
              "type": "plain_text",
              "text": "Approve"
            },
            "deny": {
              "type": "plain_text",
              "text": "Cancel"
            }
          }
        },
        {
          "type": "button",
          "action_id": "jira_reject",
          "style": "danger",
          "text": {
            "type": "plain_text",
            "text": "Reject"
          },
          "value": "{{issue.key}}"
        }
      ]
    }
  ]
}
